import heapq

def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    C = capacity + 1          # charge levels 0..capacity
    K = max_swaps + 1         # swaps used 0..max_swaps
    station_set = set(stations)

    # adjacency list
    adj = [[] for _ in range(n)]
    for (u, v, m, e) in roads:
        adj[u].append((v, m, e))

    INF = float('inf')
    size = n * C * K
    dist = [INF] * size

    def idx(v, c, k):
        return (v * C + c) * K + k

    start = idx(s, capacity, 0)
    dist[start] = 0
    heap = [(0, s, capacity, 0)]

    best = None  # (minutes, swaps) for reaching t

    while heap:
        d, v, c, k = heapq.heappop(heap)
        if d != dist[idx(v, c, k)]:
            continue
        if best is not None and d > best[0]:
            break
        if v == t:
            cand = (d, k)
            if best is None or cand < best:
                best = cand
            continue  # no need to expand from t (any route onward can't improve)

        # swap action
        if v in station_set and k < max_swaps:
            nd = d + swap_time
            ni = idx(v, capacity, k + 1)
            if nd < dist[ni]:
                dist[ni] = nd
                heapq.heappush(heap, (nd, v, capacity, k + 1))

        # drive actions
        for (w, m, e) in adj[v]:
            if e > 0 and c < e:
                continue
            nc = c - e
            if nc > capacity:
                nc = capacity
            nd = d + m
            ni = idx(w, nc, k)
            if nd < dist[ni]:
                dist[ni] = nd
                heapq.heappush(heap, (nd, w, nc, k))

    return best

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    NEG = None  # marker for unreachable

    # prefix count of pinned messages: pin[i] = number of pinned among indices < i
    pin = [0] * (n + 1)
    for i, (_, _, p) in enumerate(messages):
        pin[i + 1] = pin[i] + (1 if p else 0)

    def no_pinned(lo, hi):
        # True if no pinned message with index in [lo, hi)
        if lo >= hi:
            return True
        return pin[hi] - pin[lo] == 0

    best = None

    # Empty set
    if n <= max_gap and pin[n] == 0:
        best = 0

    # dp[i] : list over used budget b -> max score with i as last kept message
    dp = [None] * n
    for i in range(n):
        length, value, _ = messages[i]
        if length > budget:
            dp[i] = None
            continue
        row = [NEG] * (budget + 1)
        # i as first kept message
        if i <= max_gap and no_pinned(0, i):
            if row[length] is NEG or value > row[length]:
                row[length] = value
        # transitions from previous kept j
        lo = max(0, i - 1 - max_gap)
        for j in range(i - 1, lo - 1, -1):
            # messages j+1 .. i-1 are dropped; must contain no pinned
            if not no_pinned(j + 1, i):
                break  # further j would include this pinned too
            prev = dp[j]
            if prev is None:
                continue
            add = value + (bonus if j == i - 1 else 0)
            for b in range(0, budget - length + 1):
                pv = prev[b]
                if pv is NEG:
                    continue
                nb = b + length
                cand = pv + add
                if row[nb] is NEG or cand > row[nb]:
                    row[nb] = cand
        dp[i] = row

        # i as last kept message
        if (n - 1 - i) <= max_gap and no_pinned(i + 1, n):
            for b in range(budget + 1):
                v = row[b]
                if v is NEG:
                    continue
                if best is None or v > best:
                    best = v

    return best

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    INF = float('inf')

    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # iterative post-order
    order = []
    stack = [0]
    while stack:
        v = stack.pop()
        order.append(v)
        for c in children[v]:
            stack.append(c)
    order.reverse()

    sub_demand = [0] * n       # total demand in subtree
    has_crit = [False] * n     # subtree contains a critical node
    dp = [None] * n            # dp[v][L] = min cost inside subtree(v), v retained, LOAD(v) = L

    for v in order:
        sd = demand[v]
        hc = bool(critical[v])
        for c in children[v]:
            sd += sub_demand[c]
            hc = hc or has_crit[c]
        sub_demand[v] = sd
        has_crit[v] = hc

        limit = root_cap if v == 0 else cap[v]
        d = demand[v]
        if d > limit:
            dp[v] = []          # cannot be retained at all
            continue

        arr = [INF] * (d + 1)
        arr[d] = 0
        for c in children[v]:
            dpc = dp[c]
            cut_allowed = not has_crit[c]
            cut_val = cut_cost[c] + penalty * sub_demand[c]
            new_len = min(limit + 1, len(arr) + (len(dpc) - 1 if dpc else 0))
            new = [INF] * new_len
            for i, a in enumerate(arr):
                if a == INF or i >= new_len:
                    continue
                if cut_allowed:
                    if a + cut_val < new[i]:
                        new[i] = a + cut_val
                if dpc:
                    jmax = min(len(dpc), new_len - i)
                    for j in range(jmax):
                        b = dpc[j]
                        if b != INF:
                            val = a + b
                            if val < new[i + j]:
                                new[i + j] = val
            # trim trailing INFs to keep arrays small
            k = len(new)
            while k > 0 and new[k - 1] == INF:
                k -= 1
            arr = new[:k]
            if not arr:
                break
        dp[v] = arr

    root = dp[0]
    if not root:
        return None
    best = min(root)
    if best == INF:
        return None
    return int(best)

from collections import deque


def run_kiosk(levels, threshold, patience, arrivals):
    # Validate ordering before doing anything.
    for i in range(1, len(arrivals)):
        if arrivals[i][0] < arrivals[i - 1][0]:
            raise ValueError("arrival times must be non-decreasing")

    n = len(levels)
    base = list(levels)   # charge of battery when placed in slot
    t0 = [0] * n          # time battery was placed in slot
    results = []
    queue = deque()
    idx = 0
    m = len(arrivals)

    def best_slot(t):
        """Slot with highest charge >= threshold at time t (lowest index on ties), or -1."""
        best = -1
        bestc = -1
        for k in range(n):
            c = base[k] + (t - t0[k])
            if c > 100:
                c = 100
            if c >= threshold and c > bestc:
                bestc = c
                best = k
        return best

    if m == 0:
        return results

    now = arrivals[0][0]
    while True:
        # Step 1: serve the queue while a slot is ready.
        while queue:
            k = best_slot(now)
            if k < 0:
                break
            ta, d, ch = queue.popleft()
            base[k] = ch
            t0[k] = now
            results.append((d, "SWAP", now, k))

        # Step 2: handle arrivals at this time.
        while idx < m and arrivals[idx][0] == now:
            ta, d, ch = arrivals[idx]
            idx += 1
            if not queue:
                k = best_slot(now)
                if k >= 0:
                    base[k] = ch
                    t0[k] = now
                    results.append((d, "SWAP", now, k))
                    continue
            queue.append((ta, d, ch))

        # Step 3: give up.
        while queue and queue[0][0] + patience <= now:
            ta, d, ch = queue.popleft()
            results.append((d, "LEFT", now))

        # Determine next event time.
        if not queue:
            if idx >= m:
                break
            now = arrivals[idx][0]
        else:
            nxt = queue[0][0] + patience
            if idx < m and arrivals[idx][0] < nxt:
                nxt = arrivals[idx][0]
            for k in range(n):
                need = threshold - base[k]
                ready = t0[k] + (need if need > 0 else 0)
                if ready < nxt:
                    nxt = ready
            now = nxt

    return results

def run_lock_manager(ops):
    log = []
    holders = {}    # res -> {tx: mode}
    xholder = {}    # res -> tx holding X (or None)
    queues = {}     # res -> list of (tx, mode)
    held = {}       # tx -> {res: mode}
    waiting = {}    # tx -> (res, mode)
    finished = set()

    def grant(tx, r, mode):
        held.setdefault(tx, {})[r] = mode
        holders.setdefault(r, {})[tx] = mode
        if mode == 'X':
            xholder[r] = tx

    def grantable(r, tx, mode):
        h = holders.get(r, {})
        if mode == 'X':
            for k in h:
                if k != tx:
                    return False
            return True
        xh = xholder.get(r)
        return xh is None or xh == tx

    def process_queue(r, i):
        q = queues.get(r)
        if not q:
            return
        while q:
            tx, mode = q[0]
            if not grantable(r, tx, mode):
                break
            q.pop(0)
            grant(tx, r, mode)
            waiting.pop(tx, None)
            log.append(("GRANT", i, tx, r, mode))

    def release(T, i):
        affected = set(held.get(T, {}).keys())
        if T in waiting:
            r, m = waiting.pop(T)
            q = queues[r]
            for k in range(len(q)):
                if q[k][0] == T:
                    del q[k]
                    break
            affected.add(r)
        for r in held.get(T, {}):
            del holders[r][T]
            if xholder.get(r) == T:
                xholder[r] = None
        held.pop(T, None)
        for r in sorted(affected):
            process_queue(r, i)
        finished.add(T)

    def detect(W, i):
        while W in waiting:
            pos_cache = {}

            def positions(r):
                d = pos_cache.get(r)
                if d is None:
                    d = {e[0]: k for k, e in enumerate(queues[r])}
                    pos_cache[r] = d
                return d

            # forward reachability from W
            F = {W}
            stack = [W]
            fprefix = {}
            fholders_done = set()
            while stack:
                u = stack.pop()
                wr = waiting.get(u)
                if wr is None:
                    continue
                r, m = wr
                q = queues[r]
                p = positions(r)[u]
                start = fprefix.get(r, 0)
                if p > start:
                    for k in range(start, p):
                        t = q[k][0]
                        if t not in F:
                            F.add(t)
                            stack.append(t)
                    fprefix[r] = p
                if m == 'X':
                    if r not in fholders_done:
                        fholders_done.add(r)
                        for t in holders.get(r, ()):
                            if t != u and t not in F:
                                F.add(t)
                                stack.append(t)
                else:
                    xh = xholder.get(r)
                    if xh is not None and xh != u and xh not in F:
                        F.add(xh)
                        stack.append(xh)

            # backward reachability to W, restricted to F
            B = {W}
            stack = [W]
            bsuffix = {}
            bdone_all = set()
            bdone_x = set()
            while stack:
                v = stack.pop()
                wr = waiting.get(v)
                if wr is not None:
                    r, m = wr
                    q = queues[r]
                    p = positions(r)[v]
                    end = bsuffix.get(r, len(q))
                    if p + 1 < end:
                        for k in range(p + 1, end):
                            t = q[k][0]
                            if t in F and t not in B:
                                B.add(t)
                                stack.append(t)
                        bsuffix[r] = p + 1
                for r, m in held.get(v, {}).items():
                    if r in bdone_all:
                        continue
                    q = queues.get(r)
                    if not q:
                        continue
                    if m == 'X':
                        bdone_all.add(r)
                        for t, tm in q:
                            if t != v and t in F and t not in B:
                                B.add(t)
                                stack.append(t)
                    else:
                        if r in bdone_x:
                            continue
                        bdone_x.add(r)
                        for t, tm in q:
                            if tm == 'X' and t != v and t in F and t not in B:
                                B.add(t)
                                stack.append(t)

            if len(B) <= 1:
                break
            victim = max(B)
            log.append(("ABORT", i, victim))
            release(victim, i)

    for i, op in enumerate(ops):
        kind = op[0]
        T = op[1]
        if T in waiting or T in finished:
            log.append(("IGNORED", i, T))
            continue
        if kind == "COMMIT":
            log.append(("COMMIT", i, T))
            release(T, i)
            continue
        M = kind
        R = op[2]
        h = held.get(T, {})
        cur = h.get(R)
        if cur == 'X' or (cur == 'S' and M == 'S'):
            log.append(("HELD", i, T, R))
        elif cur == 'S':
            hr = holders[R]
            if len(hr) == 1:
                hr[T] = 'X'
                h[R] = 'X'
                xholder[R] = T
                log.append(("GRANT", i, T, R, 'X'))
            else:
                q = queues.setdefault(R, [])
                idx = 0
                while idx < len(q) and q[idx][1] == 'X' and q[idx][0] in hr:
                    idx += 1
                q.insert(idx, (T, 'X'))
                waiting[T] = (R, 'X')
                log.append(("WAIT", i, T, R, 'X'))
                detect(T, i)
        else:
            q = queues.setdefault(R, [])
            hr = holders.get(R, {})
            if M == 'S':
                compatible = xholder.get(R) is None
            else:
                compatible = not hr
            if not q and compatible:
                grant(T, R, M)
                log.append(("GRANT", i, T, R, M))
            else:
                q.append((T, M))
                waiting[T] = (R, M)
                log.append(("WAIT", i, T, R, M))
                detect(T, i)

    return log

def simulate_vending(prices, stock, bank, events, timeout):
    ACCEPTED = (5, 10, 25, 100)

    # Validate time ordering before producing anything.
    prev_t = None
    for ev in events:
        t = ev[0]
        if prev_t is not None and t < prev_t:
            raise ValueError("events are not in non-decreasing time order")
        prev_t = t

    # Copy state so inputs are not mutated.
    bank_state = {d: 0 for d in ACCEPTED}
    for d, c in bank.items():
        if d in bank_state:
            bank_state[d] += c
    stock_state = dict(stock)
    escrow = []          # ordered list of coin values
    last = None          # time of most recent activity
    log = []

    def escrow_tuple():
        return tuple(sorted(escrow, reverse=True))

    def maybe_timeout(current_t):
        # Return escrow automatically if its deadline has passed before current_t.
        nonlocal escrow
        if escrow and last is not None:
            deadline = last + timeout
            if current_t is None or current_t >= deadline:
                log.append(("TIMEOUT", deadline, escrow_tuple()))
                escrow = []

    for t, kind, arg in events:
        maybe_timeout(t)

        if kind == "coin":
            v = arg
            if v not in ACCEPTED or len(escrow) >= 10:
                log.append(("REJECT", t, v))
            else:
                escrow.append(v)
                last = t

        elif kind == "select":
            last = t
            s = arg
            if s not in prices:
                log.append(("UNKNOWN", t, s))
            elif stock_state.get(s, 0) == 0:
                log.append(("SOLD_OUT", t, s))
            else:
                price = prices[s]
                total = sum(escrow)
                if total < price:
                    log.append(("NEED", t, price - total))
                else:
                    # Attempt sale: move escrow into bank, make change greedily.
                    saved_bank = dict(bank_state)
                    for c in escrow:
                        bank_state[c] += 1
                    remaining = total - price
                    change = []
                    for d in (100, 25, 10, 5):
                        k = min(bank_state[d], remaining // d)
                        if k > 0:
                            bank_state[d] -= k
                            change.extend([d] * k)
                            remaining -= k * d
                    if remaining == 0:
                        stock_state[s] -= 1
                        escrow = []
                        log.append(("VEND", t, s, tuple(change)))
                    else:
                        bank_state = saved_bank
                        log.append(("EXACT_ONLY", t, s))

        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, escrow_tuple()))
                escrow = []

    # Pending automatic return after the last event.
    maybe_timeout(None)

    final_bank = (bank_state[5], bank_state[10], bank_state[25], bank_state[100])
    return log, final_bank

import re

_NAME_RE = re.compile(r"[a-z0-9_]+")
_WORD_RE = re.compile(r"[a-z]+")
_ACTION_LIST_RE = re.compile(r"[a-z]+(,[a-z]+)*")
_RES_SEG_RE = re.compile(r"\*\*|\*|[a-z0-9._-]+")
_PATH_SEG_RE = re.compile(r"[a-z0-9._-]+")


def _is_name(s):
    return isinstance(s, str) and _NAME_RE.fullmatch(s) is not None


def _is_word(s):
    return isinstance(s, str) and _WORD_RE.fullmatch(s) is not None


def _split_slash_path(s, seg_re):
    """Return list of segments if s is a valid path/resource, else None."""
    if not isinstance(s, str) or not s.startswith("/"):
        return None
    if s == "/":
        return []
    segs = s[1:].split("/")
    for seg in segs:
        if not seg or seg_re.fullmatch(seg) is None:
            return None
    return segs


def _match_resource(pattern, has_dstar, path):
    """pattern: list of resource segments; path: list of path segments."""
    m = len(pattern)
    n = len(path)
    if not has_dstar:
        if m != n:
            return False
        for p, s in zip(pattern, path):
            if p != "*" and p != s:
                return False
        return True

    # NFA-style simulation: set of pattern positions reachable.
    def closure(states):
        stack = list(states)
        out = set(states)
        while stack:
            i = stack.pop()
            if i < m and pattern[i] == "**" and (i + 1) not in out:
                out.add(i + 1)
                stack.append(i + 1)
        return out

    states = closure({0})
    for seg in path:
        nxt = set()
        for i in states:
            if i >= m:
                continue
            p = pattern[i]
            if p == "**":
                nxt.add(i)
            elif p == "*" or p == seg:
                nxt.add(i + 1)
        if not nxt:
            return False
        states = closure(nxt)
    return m in states


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    parsed_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        # principal
        if principal == "*":
            p_kind, p_name, p_spec = "*", None, 0
        elif principal.startswith("user:") and _is_name(principal[5:]):
            p_kind, p_name, p_spec = "user", principal[5:], 2
        elif principal.startswith("group:") and _is_name(principal[6:]):
            p_kind, p_name, p_spec = "group", principal[6:], 1
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        # action
        if action == "*":
            actions, a_spec = None, 0
        elif _ACTION_LIST_RE.fullmatch(action) is not None:
            actions, a_spec = set(action.split(",")), 1
        else:
            raise ValueError(f"rule {i}: bad action {action!r}")
        # resource
        segs = _split_slash_path(resource, _RES_SEG_RE)
        if segs is None:
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        has_dstar = "**" in segs
        L = sum(1 for s in segs if s != "*" and s != "**")
        parsed_rules.append(
            (effect, p_kind, p_name, actions, segs, has_dstar, (L, p_spec, a_spec))
        )

    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req
        if not _is_name(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list) or not all(_is_name(g) for g in groups):
            raise ValueError(f"request {j}: bad groups")
        if not _is_word(action):
            raise ValueError(f"request {j}: bad action {action!r}")
        psegs = _split_slash_path(path, _PATH_SEG_RE)
        if psegs is None:
            raise ValueError(f"request {j}: bad path {path!r}")
        parsed_requests.append((user, set(groups), action, psegs))

    results = []
    for user, groups, action, psegs in parsed_requests:
        best = None
        best_idx = []
        for i, (effect, p_kind, p_name, actions, segs, has_dstar, spec) in enumerate(parsed_rules):
            if p_kind == "user":
                if p_name != user:
                    continue
            elif p_kind == "group":
                if p_name not in groups:
                    continue
            if actions is not None and action not in actions:
                continue
            if best is not None and spec < best:
                continue  # cannot improve or tie
            if not _match_resource(segs, has_dstar, psegs):
                continue
            if best is None or spec > best:
                best = spec
                best_idx = [i]
            else:
                best_idx.append(i)
        if best is None:
            results.append("DENY by default")
            continue
        deny = [i for i in best_idx if parsed_rules[i][0] == "DENY"]
        if deny:
            results.append(f"DENY by rule {deny[0]}")
        else:
            results.append(f"ALLOW by rule {best_idx[0]}")
    return results

import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _type_name(v) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _copy(v):
    """Deep copy of a JSON-like value (dicts/lists copied, scalars shared)."""
    if isinstance(v, dict):
        return {k: _copy(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_copy(x) for x in v]
    return v


def _child_path(parent: str, name: str) -> str:
    if _IDENT_RE.fullmatch(name) and name.isascii():
        return parent + "." + name
    return parent + "[" + json.dumps(name, ensure_ascii=False) + "]"


def _merge(target: dict, overlay: dict, path: str, layer: int, warnings: list) -> None:
    for key, value in overlay.items():
        if not isinstance(key, str):
            raise TypeError(f"layer {layer}: non-string key at {path}")

        if key.startswith("-"):
            kind = "delete"
            name = key[1:]
        elif key.endswith("+"):
            kind = "append"
            name = key[:-1]
        else:
            kind = "set"
            name = key

        if name == "":
            raise ValueError(f"layer {layer}: empty key name at {path}")

        qpath = _child_path(path, name)

        if kind == "delete":
            if value is not None:
                raise ValueError(f"layer {layer}: delete directive needs null at {qpath}")
            if name in target:
                del target[name]
            else:
                warnings.append(f"layer {layer}: delete of missing key at {qpath}")

        elif kind == "append":
            if not isinstance(value, list):
                raise ValueError(f"layer {layer}: append directive needs a list at {qpath}")
            if name not in target:
                target[name] = _copy(value)
            elif isinstance(target[name], list):
                target[name].extend(_copy(x) for x in value)
            else:
                raise ValueError(
                    f"layer {layer}: cannot append to {_type_name(target[name])} at {qpath}"
                )

        else:  # set
            if name in target:
                old_t = _type_name(target[name])
                new_t = _type_name(value)
                if old_t != new_t:
                    warnings.append(
                        f"layer {layer}: type change at {qpath}: {old_t} -> {new_t}"
                    )
            if isinstance(value, dict):
                if name in target and isinstance(target[name], dict):
                    _merge(target[name], value, qpath, layer, warnings)
                else:
                    target[name] = {}
                    _merge(target[name], value, qpath, layer, warnings)
            else:
                target[name] = _copy(value)


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    for idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {idx} is not a dict")
        _merge(result, layer, "$", idx, warnings)

    return result, warnings

import re
from datetime import date as _date

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_KINDS = ("credit", "debit", "fee")


def _to_cents(s: str) -> int:
    """Convert a validated decimal string (optional sign, up to 2 decimals) to integer cents."""
    neg = s.startswith("-")
    if neg:
        s = s[1:]
    if "." in s:
        ip, fp = s.split(".", 1)
    else:
        ip, fp = s, ""
    fp = (fp + "00")[:2]
    cents = int(ip) * 100 + int(fp)
    return -cents if neg else cents


def _money(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    a = abs(cents)
    return f"{sign}{a // 100:,}.{a % 100:02d}"


def _valid_date(s) -> bool:
    if not isinstance(s, str) or not _DATE_RE.fullmatch(s):
        return False
    y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
    if not (1900 <= y <= 2999):
        return False
    try:
        _date(y, m, d)
    except ValueError:
        return False
    return True


def _valid_memo(memo) -> bool:
    if not isinstance(memo, str):
        return False
    if not memo.split():
        return False
    for ch in memo:
        o = ord(ch)
        if o < 32 or o == 127:
            return False
    return True


def render_statement(opening, entries) -> list[str]:
    # --- validation ---
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if not _OPENING_RE.fullmatch(opening):
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    prev_date = None
    for i, e in enumerate(entries):
        if not isinstance(e, tuple) or len(e) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")
        date, kind, amount, memo = e
        if not _valid_date(date):
            raise ValueError(f"entry {i}: bad date {date!r}")
        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")
        prev_date = date
        if not (isinstance(kind, str) and kind in _KINDS):
            raise ValueError(f"entry {i}: bad kind {kind!r}")
        if (not isinstance(amount, str) or not _AMOUNT_RE.fullmatch(amount)
                or _to_cents(amount) == 0):
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        if not _valid_memo(memo):
            raise ValueError(f"entry {i}: bad memo")

    # --- processing ---
    balance = _to_cents(opening)
    lines = ["Opening balance: " + _money(balance)]
    counts = {"credit": 0, "debit": 0, "fee": 0}
    fee_dates = set()

    def render(date, kind, cents, memo):
        nonlocal balance
        if kind == "credit":
            balance += cents
            sign = "+"
        else:
            balance -= cents
            sign = "-"
        counts[kind] += 1
        m = " ".join(memo.split())
        if len(m) > 20:
            m = m[:19] + "~"
        amt = sign + _money(cents)
        flag = " OD" if balance < 0 else ""
        lines.append(f"{date}  {m:<20}  {amt:>14}  {_money(balance):>15}{flag}")

    for date, kind, amount, memo in entries:
        cents = _to_cents(amount)
        render(date, kind, cents, memo)
        if kind == "debit" and balance < 0 and date not in fee_dates:
            fee_dates.add(date)
            render(date, "fee", 2500, "OVERDRAFT FEE")

    lines.append("Closing balance: " + _money(balance))
    lines.append(
        f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}"
    )
    return lines

import re

_PART = r"(?:0|[1-9][0-9]*)"
_VERSION_RE = re.compile(
    rf"({_PART})\.({_PART})\.({_PART})(?:~rc([1-9][0-9]*))?"
)
_MAJOR_STAR_RE = re.compile(rf"({_PART})\.\*")
_MAJOR_MINOR_STAR_RE = re.compile(rf"({_PART})\.({_PART})\.\*")
_AT_RE = re.compile(rf"@({_PART})\.({_PART})")


def _parse_version(text):
    """Return a sortable key (X, Y, Z, is_release, N) or None if invalid."""
    if not isinstance(text, str):
        return None
    m = _VERSION_RE.fullmatch(text)
    if m is None:
        return None
    x, y, z, n = m.groups()
    if n is None:
        return (int(x), int(y), int(z), 1, 0)
    return (int(x), int(y), int(z), 0, int(n))


def _parse_clause(clause):
    """Return a predicate over version keys, or None if the clause is invalid."""
    if clause == "*":
        return lambda k: True

    # Comparison operators (check two-char operators before one-char ones).
    for op in ("!=", ">=", "<=", "=", ">", "<"):
        if clause.startswith(op):
            v = _parse_version(clause[len(op):])
            if v is None:
                return None
            if op == "!=":
                return lambda k, v=v: k != v
            if op == ">=":
                return lambda k, v=v: k >= v
            if op == "<=":
                return lambda k, v=v: k <= v
            if op == "=":
                return lambda k, v=v: k == v
            if op == ">":
                return lambda k, v=v: k > v
            return lambda k, v=v: k < v

    m = _AT_RE.fullmatch(clause)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda k, x=x, y=y: k[0] == x and k[1] >= y

    m = _MAJOR_MINOR_STAR_RE.fullmatch(clause)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda k, x=x, y=y: k[0] == x and k[1] == y

    m = _MAJOR_STAR_RE.fullmatch(clause)
    if m:
        x = int(m.group(1))
        return lambda k, x=x: k[0] == x

    v = _parse_version(clause)
    if v is not None:
        return lambda k, v=v: k == v

    return None


def pick_version(available, constraint) -> str | None:
    # 1. available must be a list
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    # 2. each element must be a valid version string
    keys = []
    for i, element in enumerate(available):
        key = _parse_version(element)
        if key is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        keys.append(key)

    # 3. constraint must be a str
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    # 4. constraint must not be empty / spaces only
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    # 5. parse alternatives and clauses
    alternatives = []  # list of (allow_rc, [predicates])
    for a, alt_text in enumerate(constraint.split("|"), start=1):
        alt = alt_text.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")
        predicates = []
        for c, clause_text in enumerate(alt.split(","), start=1):
            clause = clause_text.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            predicates.append(pred)
        alternatives.append((allow_rc, predicates))

    # Matching
    best = None
    best_key = None
    for element, key in zip(available, keys):
        is_rc = key[3] == 0
        matched = False
        for allow_rc, predicates in alternatives:
            if is_rc and not allow_rc:
                continue
            if all(pred(key) for pred in predicates):
                matched = True
                break
        if matched and (best_key is None or key > best_key):
            best = element
            best_key = key

    return best

import re

_KEY_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_-]*')
_INT_RE = re.compile(r'-?(0|[1-9][0-9]*)')
_ESCAPES = {'\\': '\\', '"': '"', 'n': '\n', 't': '\t'}


def _convert(txt):
    """Return (ok, value) or (False, error_message)."""
    if txt[0] == '"':
        out = []
        i = 1
        n = len(txt)
        while i < n:
            c = txt[i]
            if c == '\\':
                if i + 1 >= n or txt[i + 1] not in _ESCAPES:
                    return False, "bad escape"
                out.append(_ESCAPES[txt[i + 1]])
                i += 2
                continue
            if c == '"':
                if i != n - 1:
                    return False, "bad string"
                return True, ''.join(out)
            out.append(c)
            i += 1
        return False, "bad string"
    if txt == "true":
        return True, True
    if txt == "false":
        return True, False
    if txt == "null":
        return True, None
    if _INT_RE.fullmatch(txt):
        return True, int(txt)
    return True, txt


def parse_outline(text: str) -> tuple:
    lines = text.split('\n')
    stack = []          # entries: (indent, kind, container)
    pending = None      # (indent, container, key) of previous opener, or None
    root = None

    for ln, line in enumerate(lines, 1):
        rest = line.lstrip(' \t')
        if not rest:
            continue                      # blank
        if rest[0] == '#':
            continue                      # comment
        indent = len(line) - len(rest)
        if '\t' in line[:indent]:
            return ("error", ln, "tab in indentation")

        # --- entry syntax ---
        key = None
        if rest == '-' or rest.startswith('- '):
            kind = 'list'
            txt = rest[2:].strip(' ')
        else:
            colon = rest.find(':')
            if colon < 0:
                return ("error", ln, "invalid entry")
            key = rest[:colon]
            if not _KEY_RE.fullmatch(key):
                return ("error", ln, "invalid entry")
            after = rest[colon + 1:]
            if after.strip(' ') == '':
                txt = ''
            elif after[0] != ' ':
                return ("error", ln, "invalid entry")
            else:
                txt = after.strip(' ')
            kind = 'map'

        opener = (txt == '')
        value = None
        if not opener:
            ok, value = _convert(txt)
            if not ok:
                return ("error", ln, value)

        # --- structure ---
        if not stack:
            if indent != 0:
                return ("error", ln, "unexpected indent")
            container = {} if kind == 'map' else []
            root = container
            stack.append((0, kind, container))
        elif pending is not None and indent > pending[0]:
            container = {} if kind == 'map' else []
            p_cont, p_key = pending[1], pending[2]
            if p_key is None:
                p_cont[-1] = container
            else:
                p_cont[p_key] = container
            stack.append((indent, kind, container))
        else:
            if indent > stack[-1][0]:
                return ("error", ln, "unexpected indent")
            while stack[-1][0] > indent:
                stack.pop()
            if stack[-1][0] != indent:
                return ("error", ln, "inconsistent dedent")
            if stack[-1][1] != kind:
                return ("error", ln, "mixed block")
            container = stack[-1][2]
            if kind == 'map' and key in container:
                return ("error", ln, "duplicate key '%s'" % key)

        if kind == 'map':
            container[key] = value
        else:
            container.append(value)

        pending = (indent, container, key) if opener else None

    return ("ok", root)

import re

_TOK = re.compile(r'[\[\]]|[^ \t\n\r\[\]]+')
_INT = re.compile(r'-?[0-9]+')
_BUILTINS = {'dup': 0, 'drop': 1, 'swap': 2, 'over': 3, 'rot': 4, '+': 5, '-': 6,
             '*': 7, '/': 8, '%': 9, '<': 10, '=': 11, 'if': 12, 'times': 13,
             'while': 14, 'call': 15, 'dip': 16}


def run_pile(src: str, max_steps: int) -> tuple:
    toks = _TOK.findall(src)
    n = len(toks)

    # ---------- structure check ----------
    opens = []
    i = 0
    while i < n:
        t = toks[i]
        if t == '[':
            opens.append(('[', i))
        elif t == ']':
            if not opens or opens[-1][0] != '[':
                return ('error', i, 'unmatched ]')
            opens.pop()
        elif t == ':':
            if opens:
                return ('error', i, 'misplaced :')
            if i == n - 1:
                return ('error', i, 'unclosed :')
            name = toks[i + 1]
            if name in ('[', ']', ':', ';') or name in _BUILTINS or _INT.fullmatch(name):
                return ('error', i + 1, 'bad name')
            opens.append((':', i))
            i += 1
        elif t == ';':
            if not opens or opens[-1][0] != ':':
                return ('error', i, 'unmatched ;')
            opens.pop()
        i += 1
    if opens:
        c, idx = opens[0]
        return ('error', idx, 'unclosed [' if c == '[' else 'unclosed :')

    # ---------- parse into elements (iterative) ----------
    # element: (kind, payload, idx); kinds: 0 int, 1 quot, 2 def, 3 builtin, 4 word
    top = []
    seq_stack = [top]
    disp_stack = [None]
    start_stack = []
    def_name = None
    def_idx = -1
    i = 0
    while i < n:
        t = toks[i]
        if t == '[':
            seq_stack.append([])
            disp_stack.append([])
            start_stack.append(i)
        elif t == ']':
            body = seq_stack.pop()
            disp = disp_stack.pop()
            si = start_stack.pop()
            seq_stack[-1].append((1, (body, disp), si))
            pd = disp_stack[-1]
            if pd is not None:
                pd.append(disp)
        elif t == ':':
            def_name = toks[i + 1]
            def_idx = i
            seq_stack.append([])
            disp_stack.append(None)
            i += 1
        elif t == ';':
            body = seq_stack.pop()
            disp_stack.pop()
            seq_stack[-1].append((2, (def_name, body), def_idx))
        else:
            if _INT.fullmatch(t):
                el = (0, int(t), i)
            else:
                b = _BUILTINS.get(t)
                el = (3, b, i) if b is not None else (4, t, i)
            seq_stack[-1].append(el)
            pd = disp_stack[-1]
            if pd is not None:
                pd.append(t)
        i += 1

    # ---------- execute ----------
    st = []
    defs = {}
    frames = [[top, 0, 0, None]]
    steps = 0
    while frames:
        fr = frames[-1]
        seq = fr[0]
        pc = fr[1]
        if pc >= len(seq):
            k = fr[2]
            if k == 0:
                frames.pop()
            elif k == 1:
                st.append(fr[3])
                frames.pop()
            elif k == 2:
                fr[3] -= 1
                if fr[3] > 0:
                    fr[1] = 0
                else:
                    frames.pop()
            else:
                d = fr[3]
                if d[0] == 0:
                    if not st:
                        return ('error', d[3], 'stack underflow')
                    v = st.pop()
                    if type(v) is not int:
                        return ('error', d[3], 'type error')
                    if v != 0:
                        fr[0] = d[2]
                        fr[1] = 0
                        d[0] = 1
                    else:
                        frames.pop()
                else:
                    fr[0] = d[1]
                    fr[1] = 0
                    d[0] = 0
            continue
        el = seq[pc]
        fr[1] = pc + 1
        steps += 1
        if steps > max_steps:
            return ('error', el[2], 'step limit exceeded')
        k = el[0]
        if k <= 1:
            st.append(el[1])
        elif k == 4:
            body = defs.get(el[1])
            if body is None:
                return ('error', el[2], "unknown word '%s'" % el[1])
            frames.append([body, 0, 0, None])
        elif k == 2:
            defs[el[1][0]] = el[1][1]
        else:
            b = el[1]
            idx = el[2]
            L = len(st)
            if b == 0:
                if L < 1: return ('error', idx, 'stack underflow')
                st.append(st[-1])
            elif b == 1:
                if L < 1: return ('error', idx, 'stack underflow')
                st.pop()
            elif b == 2:
                if L < 2: return ('error', idx, 'stack underflow')
                st[-1], st[-2] = st[-2], st[-1]
            elif b == 3:
                if L < 2: return ('error', idx, 'stack underflow')
                st.append(st[-2])
            elif b == 4:
                if L < 3: return ('error', idx, 'stack underflow')
                st[-3], st[-2], st[-1] = st[-2], st[-1], st[-3]
            elif b <= 11:
                if L < 2: return ('error', idx, 'stack underflow')
                y = st[-1]; x = st[-2]
                if type(x) is not int or type(y) is not int:
                    return ('error', idx, 'type error')
                st.pop()
                if b == 5: st[-1] = x + y
                elif b == 6: st[-1] = x - y
                elif b == 7: st[-1] = x * y
                elif b == 8:
                    if y == 0: return ('error', idx, 'division by zero')
                    st[-1] = x // y
                elif b == 9:
                    if y == 0: return ('error', idx, 'division by zero')
                    st[-1] = x % y
                elif b == 10: st[-1] = 1 if x < y else 0
                else: st[-1] = 1 if x == y else 0
            elif b == 12:
                if L < 3: return ('error', idx, 'stack underflow')
                c = st[-3]; t = st[-2]; f = st[-1]
                if type(c) is not int or type(t) is not tuple or type(f) is not tuple:
                    return ('error', idx, 'type error')
                del st[-3:]
                frames.append([t[0] if c != 0 else f[0], 0, 0, None])
            elif b == 13:
                if L < 2: return ('error', idx, 'stack underflow')
                q = st[-2]; cnt = st[-1]
                if type(q) is not tuple or type(cnt) is not int:
                    return ('error', idx, 'type error')
                if cnt < 0: return ('error', idx, 'negative count')
                del st[-2:]
                if cnt > 0 and q[0]:
                    frames.append([q[0], 0, 2, cnt])
            elif b == 14:
                if L < 2: return ('error', idx, 'stack underflow')
                c = st[-2]; bd = st[-1]
                if type(c) is not tuple or type(bd) is not tuple:
                    return ('error', idx, 'type error')
                del st[-2:]
                frames.append([c[0], 0, 3, [0, c[0], bd[0], idx]])
            elif b == 15:
                if L < 1: return ('error', idx, 'stack underflow')
                q = st[-1]
                if type(q) is not tuple: return ('error', idx, 'type error')
                st.pop()
                frames.append([q[0], 0, 0, None])
            else:
                if L < 2: return ('error', idx, 'stack underflow')
                a = st[-2]; q = st[-1]
                if type(q) is not tuple: return ('error', idx, 'type error')
                del st[-2:]
                frames.append([q[0], 0, 1, a])

    return ('ok', [v if type(v) is int else v[1] for v in st])

import operator


def filter_records(query: str, records: list[dict]) -> tuple:
    try:
        return _filter_records(query, records)
    except Exception:  # safety net: the function must never raise
        return ("error", 0, "unexpected end of input")


_MISSING = object()


def _is_letter(c):
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'


def _is_digit(c):
    return '0' <= c <= '9'


def _lex(q):
    tokens = []
    i, n = 0, len(q)
    keywords = {'and', 'or', 'not', 'in', 'has'}
    while i < n:
        c = q[i]
        if c in ' \t\n':
            i += 1
            continue
        if c in '()[],':
            tokens.append((c, c, i, None))
            i += 1
            continue
        two = q[i:i + 2]
        if two in ('!=', '<=', '>='):
            tokens.append(('CMP', two, i, None))
            i += 2
            continue
        if c in '=<>':
            tokens.append(('CMP', c, i, None))
            i += 1
            continue
        if _is_digit(c) or (c == '-' and i + 1 < n and _is_digit(q[i + 1])):
            j = i + 1
            while j < n and _is_digit(q[j]):
                j += 1
            text = q[i:j]
            tokens.append(('INT', text, i, int(text)))
            i = j
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    return None, ("error", i, "unterminated string")
                d = q[j]
                if d == '"':
                    j += 1
                    break
                if d == '\\':
                    if j + 1 >= n or q[j + 1] not in '"\\':
                        return None, ("error", j, "bad escape")
                    buf.append(q[j + 1])
                    j += 2
                else:
                    buf.append(d)
                    j += 1
            tokens.append(('STRING', q[i:j], i, ''.join(buf)))
            i = j
            continue
        if _is_letter(c):
            j = i + 1
            while j < n and (_is_letter(q[j]) or _is_digit(q[j]) or q[j] == '.'):
                j += 1
            text = q[i:j]
            if text in keywords:
                tokens.append((text, text, i, None))
            else:
                tokens.append(('FIELD', text, i, text))
            i = j
            continue
        return None, ("error", i, "unexpected character '%s'" % c)
    tokens.append(('END', '', n, None))
    return tokens, None


def _parse(tokens):
    nodes = []
    ops = []
    vals = []
    state = 'operand'
    cur_field = None
    cur_op = None
    lits = None

    def err(tok):
        kind, text, pos, _ = tok
        if kind == 'END':
            return ("error", pos, "unexpected end of input")
        return ("error", pos, "unexpected token '%s'" % text)

    def complete_operand():
        while ops and ops[-1] == 'not':
            ops.pop()
            child = vals.pop()
            nodes.append(('not', child))
            vals.append(len(nodes) - 1)

    def reduce_binary(allowed):
        while ops and ops[-1] in allowed:
            op = ops.pop()
            b = vals.pop()
            a = vals.pop()
            nodes.append((op, a, b))
            vals.append(len(nodes) - 1)

    for tok in tokens:
        kind, text, pos, value = tok
        if state == 'operand':
            if kind == 'not':
                ops.append('not')
            elif kind == '(':
                ops.append('(')
            elif kind == 'has':
                state = 'has_field'
            elif kind == 'FIELD':
                cur_field = text
                state = 'after_field'
            else:
                return None, err(tok)
        elif state == 'has_field':
            if kind == 'FIELD':
                nodes.append(('has', text))
                vals.append(len(nodes) - 1)
                complete_operand()
                state = 'operator'
            else:
                return None, err(tok)
        elif state == 'after_field':
            if kind == 'CMP':
                cur_op = text
                state = 'literal'
            elif kind == 'in':
                state = 'lbracket'
            else:
                return None, err(tok)
        elif state == 'literal':
            if kind in ('INT', 'STRING'):
                nodes.append(('cmp', cur_field, cur_op, value))
                vals.append(len(nodes) - 1)
                complete_operand()
                state = 'operator'
            else:
                return None, err(tok)
        elif state == 'lbracket':
            if kind == '[':
                lits = []
                state = 'list_item'
            else:
                return None, err(tok)
        elif state == 'list_item':
            if kind in ('INT', 'STRING'):
                lits.append(value)
                state = 'list_sep'
            else:
                return None, err(tok)
        elif state == 'list_sep':
            if kind == ',':
                state = 'list_item'
            elif kind == ']':
                nodes.append(('in', cur_field, lits))
                vals.append(len(nodes) - 1)
                complete_operand()
                state = 'operator'
            else:
                return None, err(tok)
        elif state == 'operator':
            if kind == 'and':
                reduce_binary(('and',))
                ops.append('and')
                state = 'operand'
            elif kind == 'or':
                reduce_binary(('and', 'or'))
                ops.append('or')
                state = 'operand'
            elif kind == ')':
                reduce_binary(('and', 'or'))
                if ops and ops[-1] == '(':
                    ops.pop()
                    complete_operand()
                else:
                    return None, err(tok)
            elif kind == 'END':
                reduce_binary(('and', 'or'))
                if ops:
                    return None, err(tok)
                return (nodes, vals[0]), None
            else:
                return None, err(tok)
    # Should not reach here since END always terminates.
    return None, ("error", tokens[-1][2], "unexpected end of input")


def _evaluate(nodes, root, records):
    cols = {}

    def col(f):
        c = cols.get(f)
        if c is None:
            c = [r.get(f, _MISSING) for r in records]
            cols[f] = c
        return c

    M = _MISSING
    cmp_funcs = {'<': operator.lt, '<=': operator.le,
                 '>': operator.gt, '>=': operator.ge}
    results = [None] * len(nodes)
    for idx, node in enumerate(nodes):
        t = node[0]
        if t == 'cmp':
            _, f, op, lit = node
            c = col(f)
            if op == '=':
                res = [1 if v is M else (2 if v == lit else 0) for v in c]
            elif op == '!=':
                res = [1 if v is M else (0 if v == lit else 2) for v in c]
            else:
                fn = cmp_funcs[op]
                is_str = isinstance(lit, str)
                res = [1 if (v is M or isinstance(v, str) != is_str)
                       else (2 if fn(v, lit) else 0) for v in c]
        elif t == 'in':
            _, f, lits = node
            s = set(lits)
            c = col(f)
            res = [1 if v is M else (2 if v in s else 0) for v in c]
        elif t == 'has':
            c = col(node[1])
            res = [0 if v is M else 2 for v in c]
        elif t == 'not':
            res = [2 - x for x in results[node[1]]]
        elif t == 'and':
            res = list(map(min, results[node[1]], results[node[2]]))
        else:  # 'or'
            res = list(map(max, results[node[1]], results[node[2]]))
        results[idx] = res
    final = results[root]
    return [i for i, x in enumerate(final) if x == 2]


def _filter_records(query, records):
    tokens, error = _lex(query)
    if error is not None:
        return error
    parsed, error = _parse(tokens)
    if error is not None:
        return error
    nodes, root = parsed
    return ("ok", _evaluate(nodes, root, records))

import re

_TOKEN_RE = re.compile(r'[0-9]+|[a-z_][a-z0-9_]*|<=|>=|==|!=|[-+*/%^()?:<>]| |.', re.DOTALL)
_OPS = {'<=', '>=', '==', '!=', '+', '-', '*', '/', '%', '^', '(', ')', '?', ':', '<', '>'}
_BIN_PREC = {'<': 2, '<=': 2, '>': 2, '>=': 2, '==': 2, '!=': 2,
             '+': 3, '-': 3, '*': 4, '/': 4, '%': 4, '^': 6}
_INT, _NAME, _OP, _BAD, _END = 0, 1, 2, 3, 4


def _to_int(text):
    # avoid Python's int<->str digit limit for huge literals
    if len(text) <= 4000:
        return int(text)
    v = 0
    for i in range(0, len(text), 4000):
        chunk = text[i:i + 4000]
        v = v * 10 ** len(chunk) + int(chunk)
    return v


def _err(tok):
    kind, text, pos = tok
    if kind == _END:
        return ("error", pos, "unexpected end of input")
    if kind == _BAD:
        return ("error", pos, "unexpected character '%s'" % text)
    return ("error", pos, "unexpected token '%s'" % text)


def evaluate(src: str, env: dict) -> tuple:
    # ---------------- tokenize ----------------
    tokens = []
    for m in _TOKEN_RE.finditer(src):
        t = m.group()
        if t == ' ':
            continue
        c = t[0]
        if '0' <= c <= '9':
            kind = _INT
        elif c == '_' or 'a' <= c <= 'z':
            kind = _NAME
        elif t in _OPS:
            kind = _OP
        else:
            kind = _BAD
        tokens.append((kind, t, m.start()))
    tokens.append((_END, '', len(src)))

    # ---------------- parse (shunting-yard -> code with jumps) ----------------
    code = []
    ops = []          # entries: (kind, prec, pos, aux)
    expect_operand = True

    def reduce(entry):
        k = entry[0]
        if k == 'bin':
            code.append(('bin', entry[3], entry[2]))
        elif k == 'neg':
            code.append(('neg',))
        elif k == '?:':
            code[entry[3]] = ('jmp', len(code))

    for tok in tokens:
        kind, text, pos = tok
        if expect_operand:
            if kind == _INT:
                code.append(('push', _to_int(text)))
                expect_operand = False
            elif kind == _NAME:
                code.append(('load', pos, text))
                expect_operand = False
            elif kind == _OP and text == '(':
                ops.append(('(', 0, pos, None))
            elif kind == _OP and text == '-':
                ops.append(('neg', 5, pos, None))
            else:
                return _err(tok)
        else:
            if kind != _OP:
                return _err(tok)
            p = _BIN_PREC.get(text)
            if p is not None:
                if p == 6:
                    pass  # right-assoc, nothing has higher precedence
                elif p == 2:
                    while ops and ops[-1][1] > 2:
                        reduce(ops.pop())
                    if ops and ops[-1][1] == 2:
                        return _err(tok)  # non-associative comparison
                else:
                    while ops and ops[-1][1] >= p:
                        reduce(ops.pop())
                ops.append(('bin', p, pos, text))
                expect_operand = True
            elif text == '?':
                while ops and ops[-1][1] > 1:
                    reduce(ops.pop())
                ops.append(('?', 1, pos, len(code)))
                code.append(None)  # jz placeholder
                expect_operand = True
            elif text == ':':
                while ops and ops[-1][0] != '(' and ops[-1][0] != '?':
                    reduce(ops.pop())
                if not ops or ops[-1][0] == '(':
                    return _err(tok)
                q = ops.pop()
                jmp_idx = len(code)
                code.append(None)  # jmp placeholder
                code[q[3]] = ('jz', len(code))
                ops.append(('?:', 1, q[2], jmp_idx))
                expect_operand = True
            elif text == ')':
                while ops and ops[-1][0] != '(' and ops[-1][0] != '?':
                    reduce(ops.pop())
                if not ops or ops[-1][0] == '?':
                    return _err(tok)
                ops.pop()
            else:
                return _err(tok)
    # END token
    while ops and ops[-1][0] != '(' and ops[-1][0] != '?':
        reduce(ops.pop())
    if ops:
        return _err(tokens[-1])

    # ---------------- evaluate ----------------
    stack = []
    pc = 0
    n = len(code)
    while pc < n:
        ins = code[pc]
        k = ins[0]
        if k == 'push':
            stack.append(ins[1])
        elif k == 'load':
            name = ins[2]
            if name in env:
                stack.append(env[name])
            else:
                return ("error", ins[1], "unknown name '%s'" % name)
        elif k == 'bin':
            op = ins[1]
            b = stack.pop()
            a = stack[-1]
            if op == '+':
                r = a + b
            elif op == '-':
                r = a - b
            elif op == '*':
                r = a * b
            elif op == '/':
                if b == 0:
                    return ("error", ins[2], "division by zero")
                r = a // b
            elif op == '%':
                if b == 0:
                    return ("error", ins[2], "division by zero")
                r = a % b
            elif op == '^':
                if b < 0:
                    return ("error", ins[2], "negative exponent")
                if b > 256:
                    return ("error", ins[2], "exponent too large")
                r = a ** b
            elif op == '<':
                r = 1 if a < b else 0
            elif op == '<=':
                r = 1 if a <= b else 0
            elif op == '>':
                r = 1 if a > b else 0
            elif op == '>=':
                r = 1 if a >= b else 0
            elif op == '==':
                r = 1 if a == b else 0
            else:  # '!='
                r = 1 if a != b else 0
            stack[-1] = r
        elif k == 'neg':
            stack[-1] = -stack[-1]
        elif k == 'jz':
            if stack.pop() == 0:
                pc = ins[1]
                continue
        else:  # 'jmp'
            pc = ins[1]
            continue
        pc += 1
    return ("ok", stack[-1])

import re
from fractions import Fraction
from math import gcd

_LIT = re.compile(r'[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?')


def _parse(x: str) -> Fraction:
    if not isinstance(x, str) or _LIT.fullmatch(x) is None:
        raise ValueError("invalid decimal literal")
    s = x
    neg = False
    if s[0] in '+-':
        neg = s[0] == '-'
        s = s[1:]
    exp = 0
    m = re.search(r'[eE]', s)
    if m:
        exp = int(s[m.start() + 1:])
        s = s[:m.start()]
    if '.' in s:
        ip, fp = s.split('.')
    else:
        ip, fp = s, ''
    digits = int((ip + fp) or '0')
    e = exp - len(fp)
    if e >= 0:
        val = Fraction(digits * 10 ** e)
    else:
        val = Fraction(digits, 10 ** (-e))
    return -val if neg else val


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    v = _parse(x)
    if max_num < 0 or max_den < 1:
        raise ValueError("bad bounds")
    N, D = max_num, max_den
    neg = v < 0
    if neg:
        v = -v

    # Stern-Brocot walk with l < v < u, l and u adjacent.
    p0, q0 = 0, 1      # lower bound (always a valid candidate)
    p1, q1 = 1, 0      # upper bound (1/0 = infinity initially)
    INF = float('inf')

    while True:
        if Fraction(p0, q0) == v:
            a, b = p0, q0
            break
        if q1 > 0 and Fraction(p1, q1) == v:
            a, b = p1, q1
            break
        mp, mq = p0 + p1, q0 + q1
        if mp > N or mq > D:
            # best lower is l, best upper is u (if finite)
            dl = v - Fraction(p0, q0)
            if q1 == 0:
                a, b = p0, q0
            else:
                du = Fraction(p1, q1) - v
                if dl < du:
                    a, b = p0, q0
                elif du < dl:
                    a, b = p1, q1
                else:
                    if q0 <= q1:   # smaller denominator, or equal -> closer to zero (l)
                        a, b = p0, q0
                    else:
                        a, b = p1, q1
            break
        m = Fraction(mp, mq)
        if v < m:
            # move u toward l: terms (k*p0+p1)/(k*q0+q1)
            r = (p1 - v * q1) / (v * q0 - p0)
            kx = r.numerator // r.denominator
            kc = (D - q1) // q0
            if p0 > 0:
                kc = min(kc, (N - p1) // p0)
            k = min(kx, kc)
            p1, q1 = k * p0 + p1, k * q0 + q1
        else:
            # move l toward u: terms (p0+k*p1)/(q0+k*q1)
            r = (v * q0 - p0) / (p1 - v * q1)
            kx = r.numerator // r.denominator
            kc = INF
            if q1 > 0:
                kc = (D - q0) // q1
            if p1 > 0:
                kc = min(kc, (N - p0) // p1)
            k = kx if kc == INF else min(kx, kc)
            p0, q0 = p0 + k * p1, q0 + k * q1

    g = gcd(a, b)
    a //= g
    b //= g
    if a == 0:
        return "0/1"
    if neg:
        a = -a
    return f"{a}/{b}"

import random


def run_ops(ops: list[tuple]) -> list:
    rnd = random.random
    # node layout: [key, value, prio, left, right, size, sum]
    EMPTY = [0, 0, -1.0, None, None, 0, 0]
    EMPTY[3] = EMPTY
    EMPTY[4] = EMPTY
    versions = [EMPTY]
    out = []
    append = out.append

    def merge(a, b):
        if a is EMPTY:
            return b
        if b is EMPTY:
            return a
        if a[2] > b[2]:
            r = merge(a[4], b)
            l = a[3]
            return [a[0], a[1], a[2], l, r, l[5] + r[5] + 1, l[6] + r[6] + a[1]]
        else:
            l = merge(a, b[3])
            r = b[4]
            return [b[0], b[1], b[2], l, r, l[5] + r[5] + 1, l[6] + r[6] + b[1]]

    def count_le(t, x):
        res = 0
        while t is not EMPTY:
            if t[0] <= x:
                res += t[3][5] + 1
                t = t[4]
            else:
                t = t[3]
        return res

    def sum_le(t, x):
        res = 0
        while t is not EMPTY:
            if t[0] <= x:
                res += t[3][6] + t[1]
                t = t[4]
            else:
                t = t[3]
        return res

    for op in ops:
        name = op[0]
        v = op[1]
        if v < 0 or v >= len(versions):
            append("BADVER")
            continue
        root = versions[v]

        if name == "get":
            k = op[2]
            t = root
            res = None
            while t is not EMPTY:
                tk = t[0]
                if k == tk:
                    res = t[1]
                    break
                t = t[3] if k < tk else t[4]
            append(res)

        elif name == "set":
            k = op[2]
            val = op[3]
            path = []  # (node, went_left)
            t = root
            found = None
            while t is not EMPTY:
                tk = t[0]
                if k == tk:
                    found = t
                    break
                if k < tk:
                    path.append((t, True))
                    t = t[3]
                else:
                    path.append((t, False))
                    t = t[4]
            if found is not None:
                new = [k, val, found[2], found[3], found[4], found[5],
                       found[6] - found[1] + val]
                for anc, left in reversed(path):
                    if left:
                        l = new
                        r = anc[4]
                    else:
                        l = anc[3]
                        r = new
                    new = [anc[0], anc[1], anc[2], l, r,
                           l[5] + r[5] + 1, l[6] + r[6] + anc[1]]
            else:
                new = [k, val, rnd(), EMPTY, EMPTY, 1, val]
                i = len(path) - 1
                while i >= 0:
                    anc, left = path[i]
                    i -= 1
                    if new[2] > anc[2]:
                        # rotate so that new becomes parent of anc
                        if left:
                            l = new[4]
                            r = anc[4]
                            nt = [anc[0], anc[1], anc[2], l, r,
                                  l[5] + r[5] + 1, l[6] + r[6] + anc[1]]
                            nl = new[3]
                            new = [new[0], new[1], new[2], nl, nt,
                                   nl[5] + nt[5] + 1, nl[6] + nt[6] + new[1]]
                        else:
                            l = anc[3]
                            r = new[3]
                            nt = [anc[0], anc[1], anc[2], l, r,
                                  l[5] + r[5] + 1, l[6] + r[6] + anc[1]]
                            nr = new[4]
                            new = [new[0], new[1], new[2], nt, nr,
                                   nt[5] + nr[5] + 1, nt[6] + nr[6] + new[1]]
                    else:
                        if left:
                            l = new
                            r = anc[4]
                        else:
                            l = anc[3]
                            r = new
                        new = [anc[0], anc[1], anc[2], l, r,
                               l[5] + r[5] + 1, l[6] + r[6] + anc[1]]
                        # no more rotations possible above; plain copies
                        while i >= 0:
                            anc, left = path[i]
                            i -= 1
                            if left:
                                l = new
                                r = anc[4]
                            else:
                                l = anc[3]
                                r = new
                            new = [anc[0], anc[1], anc[2], l, r,
                                   l[5] + r[5] + 1, l[6] + r[6] + anc[1]]
            versions.append(new)
            append(len(versions) - 1)

        elif name == "del":
            k = op[2]
            path = []
            t = root
            found = None
            while t is not EMPTY:
                tk = t[0]
                if k == tk:
                    found = t
                    break
                if k < tk:
                    path.append((t, True))
                    t = t[3]
                else:
                    path.append((t, False))
                    t = t[4]
            if found is None:
                append("NOKEY")
                continue
            new = merge(found[3], found[4])
            for anc, left in reversed(path):
                if left:
                    l = new
                    r = anc[4]
                else:
                    l = anc[3]
                    r = new
                new = [anc[0], anc[1], anc[2], l, r,
                       l[5] + r[5] + 1, l[6] + r[6] + anc[1]]
            versions.append(new)
            append(len(versions) - 1)

        elif name == "count":
            lo = op[2]
            hi = op[3]
            if lo > hi:
                append(0)
            else:
                append(count_le(root, hi) - count_le(root, lo - 1))

        elif name == "sum":
            lo = op[2]
            hi = op[3]
            if lo > hi:
                append(0)
            else:
                append(sum_le(root, hi) - sum_le(root, lo - 1))

        elif name == "kth":
            k = op[2]
            if k < 1 or k > root[5]:
                append(None)
            else:
                t = root
                while True:
                    ls = t[3][5]
                    if k <= ls:
                        t = t[3]
                    elif k == ls + 1:
                        append(t[0])
                        break
                    else:
                        k -= ls + 1
                        t = t[4]
        else:
            # unknown op (should not happen per spec)
            append(None)

    return out

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    # key -> [value, expires_at or None, version]; least recently used first.
    # Invariant: after purge(t), every entry in `store` is unexpired at time t.
    store = OrderedDict()
    expiry_heap = []  # (expires_at, key, version) ; stale entries filtered by version
    version_counter = 0
    out = []
    last_t = None

    def purge(t):
        # Remove every entry whose expires_at <= t.
        while expiry_heap and expiry_heap[0][0] <= t:
            exp, key, ver = heapq.heappop(expiry_heap)
            entry = store.get(key)
            if entry is not None and entry[2] == ver:
                del store[key]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        purge(t)

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            expires_at = None if ttl is None else t + ttl
            version_counter += 1
            ver = version_counter

            entry = store.get(key)
            if entry is not None:
                # Existing live key: replace value and expiry, counts as a USE.
                entry[0] = value
                entry[1] = expires_at
                entry[2] = ver
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)  # evict LRU live entry
                store[key] = [value, expires_at, ver]

            if expires_at is not None:
                heapq.heappush(expiry_heap, (expires_at, key, ver))

        elif kind == "get":
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: smaller half, top is the (lower) median
    high = []   # min-heap: larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live element counts
    out = []

    def prune(heap, sign):
        # keep the invariant "top of each heap is a live element"
        while heap and delayed[sign * heap[0]]:
            delayed[sign * heap[0]] -= 1
            heapq.heappop(heap)

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))  # low top is live
            sizes["low"] -= 1
            sizes["high"] += 1
            prune(low, -1)
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))  # high top is live
            sizes["high"] -= 1
            sizes["low"] += 1
            prune(high, 1)

    def add(x):
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        # x is guaranteed to be live in the window, so low is non-empty here
        delayed[x] += 1
        if x <= -low[0]:
            sizes["low"] -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            sizes["high"] -= 1
            if high and x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k:
            old = readings[i - k]
            if old is not None:
                remove(old)
        out.append(-low[0] if sizes["low"] else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            # Leave the "\n" for the newline handler so line/col stay correct.
            i = n if end == -1 else end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            # FRACTION: "." followed by at least one digit
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            # EXPONENT: e/E, optional sign, at least one digit (all or nothing)
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
